INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, mode, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version)
VALUES ('wrangler-bar', '27', 'Wrangler Bar', 'Cloudflare CLI sign-in · macOS', 'Sign in to the Cloudflare CLI from the Mac menu bar. A small native utility that delegates default-profile browser approval to your installed Wrangler, with tool checks and troubleshooting.', '', 'Creator · Engineer', '2026', '["Swift","AppKit","Wrangler"]', 'WBR', 'amber', 'Creative Tools', 'lab', 'Open-source · Early release', '["Click or right-click the menu-bar cloud to start an explicit device sign-in.","Check installed Node and Wrangler versions and prevent duplicate sign-ins.","Keep credentials with Wrangler; the app discards login output and device codes."]', 'Make the official Cloudflare CLI sign-in easy to start from a native Mac menu without a localhost callback.', '["Built the native AppKit menu and explicit browser-approval handoff.","Added Finder-friendly tool discovery and manual executable selection.","Published universal Mac packaging, integrity checksums, and fake-CLI tests."]', '["Swift and AppKit without third-party app dependencies","Installed Wrangler device login with a checked Node runtime","Universal Apple silicon and Intel Mac bundle"]', 'Requires macOS 13.5+, a supported Node.js runtime, and Wrangler 4.119+. Version 0.1.0 supports the default-profile flow; its named-profile sign-in option fails with Wrangler. The early download is ad-hoc signed and not notarized. Browser authentication has not been tested against a real account.', 'View source and Mac release', 'https://github.com/nascarjake/wrangler-bar', '1', '0', '1')
ON CONFLICT(id) DO NOTHING;
